import type { TripActivityState } from "./src/LiveActivity.types";

export type { TripActivityState } from "./src/LiveActivity.types";

type NativeLiveActivity = {
  isSupported(): boolean;
  start(state: TripActivityState): Promise<string | null>;
  update(state: TripActivityState): Promise<void>;
  end(): Promise<void>;
};

// Lazy + guarded: native module only exists in a prebuilt dev/release build.
// Android renders an ongoing notification. iOS renders through the
// TripLiveActivity widget extension generated by the prebuild plugin.
let cached: NativeLiveActivity | null | undefined;

function native(): NativeLiveActivity | null {
  if (cached !== undefined) return cached;
  try {
    const { LiveActivityModule } = require("./src/LiveActivityModule");
    cached = LiveActivityModule as NativeLiveActivity;
  } catch {
    cached = null;
  }
  return cached;
}

export function isLiveActivityAvailable(): boolean {
  const m = native();
  try {
    return m !== null && m.isSupported();
  } catch {
    return false;
  }
}

export function startTripActivity(
  state: TripActivityState,
): Promise<string | null> {
  const m = native();
  if (!m) return Promise.resolve(null);
  return m.start(state).catch(() => null);
}

export function updateTripActivity(state: TripActivityState): Promise<void> {
  const m = native();
  if (!m) return Promise.resolve();
  return m.update(state).catch(() => {});
}

export function endTripActivity(): Promise<void> {
  const m = native();
  if (!m) return Promise.resolve();
  return m.end().catch(() => {});
}

export {
  useTripLiveActivity,
  type TripLiveActivityToken,
} from "./src/useTripLiveActivity";
